/* @autogenerated */
package net.civeira.phylax.common.infrastructure.exceptionmapper;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.ws.rs.core.HttpHeaders;
import jakarta.ws.rs.core.Response;
import jakarta.ws.rs.ext.ExceptionMapper;
import jakarta.ws.rs.ext.Provider;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.common.exception.StepUpRequiredException;

/**
 * Maps step-up exceptions to HTTP 401 responses (RFC 9470).
 *
 * The response carries {@code WWW-Authenticate: Bearer error="insufficient_user_authentication"}
 * with the multi factor {@code acr_values} and, when required, {@code max_age}, so the client can
 * restart the authorization request asking for the missing factor.
 */
@Slf4j
@Provider
public class StepUpRequiredExceptionMapper implements ExceptionMapper<StepUpRequiredException> {

  private final String acr;

  public StepUpRequiredExceptionMapper(@ConfigProperty(name = "security.acr.multi-factor",
      defaultValue = "urn:lugh:acr:mfa") String multiFactor) {
    this.acr = Arrays.stream(multiFactor.split(",")).map(String::trim).filter(v -> !v.isEmpty())
        .findFirst().orElse("urn:lugh:acr:mfa");
  }

  /**
   * Converts a step-up exception into an HTTP response.
   *
   * @param exception step-up exception
   * @return HTTP 401 response with the step-up challenge
   */
  @Override
  public Response toResponse(StepUpRequiredException exception) {
    if (log.isDebugEnabled()) {
      log.info("step up required", exception);
    } else if (log.isInfoEnabled()) {
      log.info("step up required");
    }
    StringBuilder challenge =
        new StringBuilder("Bearer error=\"insufficient_user_authentication\", error_description=\"")
            .append(quoted(exception.getMessage())).append("\", acr_values=\"").append(acr)
            .append('"');
    exception.getMaxAge().ifPresent(age -> challenge.append(", max_age=").append(age.toSeconds()));
    Map<String, String> error = new HashMap<>();
    error.put("reason", exception.getMessage());
    return Response.status(401).header(HttpHeaders.WWW_AUTHENTICATE, challenge.toString())
        .entity(error).build();
  }

  private static String quoted(String value) {
    return value == null ? "" : value.replace("\\", "\\\\").replace("\"", "\\\"");
  }
}
